(function(){'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const box=document.getElementById('dashPersonalizedActions'),api=window.NEXZOPersonalization;if(!box||!api)return;const s=api.snapshot(),rows=s.recommendations||[];box.innerHTML=rows.length?rows.slice(0,3).map(r=>`<div class="nx-rec-row"><div class="nx-rec-head"><div><b>${esc(r.topic)}</b><small> · ${esc(r.subject)}</small></div><span class="nx-tag">${r.durationMinutes} min</span></div><small>${esc(r.action)} · Mastery ${r.mastery}%</small><ul class="nx-why">${(r.why||[]).slice(0,2).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')+'<a class="nx-personal-link" href="personalization.html">See why these were recommended →</a>':'<div class="nx-runtime-empty">Add your subjects and daily availability to start personalized recommendations. <a href="personalization.html">Set up personalization →</a></div>'}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render,{once:true});else render();window.addEventListener('nexzo:personalization-ready',render);window.addEventListener('nexzo:personalization-updated',render)})();